<?php
namespace Tests\Feature;use App\Contracts\EmailValidatorInterface;use Tests\TestCase;
final class ApiTest extends TestCase {public function test_validation_errors_are_consistent_json():void{$this->postJson('/api/v2/validate',[])->assertStatus(422)->assertJsonPath('ok',false)->assertJsonPath('error.code','validation_failed');}public function test_single_validation_route_preserves_result_shape():void{$this->app->bind(EmailValidatorInterface::class,fn()=>new class implements EmailValidatorInterface{public function validate(string $email,array $d,array $r,bool $c):array{return ['Email'=>$email,'Verdict'=>'✅ Valid','Score'=>100];}});$this->postJson('/api/v2/validate',['email'=>'test@example.com'])->assertOk()->assertJsonPath('data.Email','test@example.com')->assertJsonPath('data.Score',100);}public function test_permutation_route():void{$this->postJson('/api/v2/permutations',['first_name'=>'John','last_name'=>'Doe','domain'=>'example.com'])->assertOk()->assertJsonFragment(['john.doe@example.com']);}}
